(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-290":{scenario:{company:"Kim Ngưu Foods",supervisor:{name:"Vũ Đức Thắng",role:{vi:"Giám đốc Kinh doanh Toàn quốc",en:"National Sales Director"}},ref_code:"PLAN-MT27",title:{vi:"Đúng kênh. Đúng chỉ tiêu. Đúng doanh thu.",en:"Right channel. Right target. Right revenue."},brief:{vi:"Bạn hoàn thiện kế hoạch kinh doanh quý 1 miền Trung PLAN-MT27 với chỉ tiêu vùng 24000 triệu đồng. Quảng Ngãi chiếm 15% doanh số năm trước nhưng 25% tiềm năng thị trường (chỉ số mô phỏng). Hợp đồng độc quyền với nhà phân phối hiện tại ở Quảng Ngãi còn hiệu lực đến 12/2027; chính sách công ty không bán trực tiếp cho điểm bán lẻ. Sửa phương án mở rộng độ phủ và chỉ tiêu quý của Quảng Ngãi, rồi lập báo cáo có căn cứ.",en:"You are finalizing the Q1 Central region sales plan PLAN-MT27 with a regional target of 24000 million VND. Quang Ngai holds 15% of last year's sales but 25% of market potential (training index). The exclusive contract with the current Quang Ngai distributor runs until 12/2027, and company policy forbids selling directly to retail outlets. Correct the coverage expansion option and Quang Ngai's quarterly target, then write an evidence-based report."},reference_title:{vi:"Chính sách kênh & bảng phân bổ chỉ tiêu đã duyệt · PLAN-MT27",en:"Approved channel policy & target allocation sheet · PLAN-MT27"},fields:[{id:"COVER_MODEL",label:{vi:"Phương án mở rộng độ phủ",en:"Coverage expansion option"},initial:"NEW-DIST",expected:"SUB-DIST",choices:["NEW-DIST","SUB-DIST","DIRECT"],reference:"Chính sách kênh phân phối",hint:{vi:"Kiểm tra điều khoản độc quyền lãnh thổ và chính sách bán hàng trực tiếp trước khi chọn mô hình.",en:"Check the territory exclusivity clause and the direct sales policy before choosing a model."}},{id:"QNG_TARGET",label:{vi:"Chỉ tiêu quý Quảng Ngãi (triệu VND)",en:"Quang Ngai quarterly target (million VND)"},initial:"3600",expected:"4560",reference:"Bảng phân bổ chỉ tiêu",ref_value:{vi:"Chỉ tiêu vùng 24000 triệu; Quảng Ngãi: 15% doanh số năm trước, 25% tiềm năng thị trường",en:"Regional target 24000 million; Quang Ngai: 15% of last year's sales, 25% of market potential"},hint:{vi:"Bản nháp chỉ dùng tỷ trọng lịch sử; mô hình đã duyệt còn tính trọng số tiềm năng.",en:"The draft uses only the historical share; the approved model also weights market potential."}}],sop32:{vi:"Chỉ tiêu tỉnh = chỉ tiêu vùng x (60% x tỷ trọng doanh số năm trước + 40% x tỷ trọng tiềm năng thị trường). Đơn vị triệu đồng; trọng số là số liệu mô phỏng.",en:"Province target = regional target x (60% x share of last year's sales + 40% x share of market potential). Unit million VND; weights are training figures."},context:{label:"SALES PLAN / PLAN-MT27",metrics:[{label:{vi:"Chỉ tiêu vùng",en:"Regional target"},value:"24,000 m VND"},{label:{vi:"Tỷ trọng doanh số QNg",en:"Quang Ngai sales share"},value:"15%"},{label:{vi:"Tỷ trọng tiềm năng QNg",en:"Quang Ngai potential share"},value:"25%"},{label:{vi:"Độc quyền NPP đến",en:"Distributor exclusivity until"},value:"12/2027"}]},crisis:{vi:"Giám sát khu vực Quảng Ngãi đề xuất: “Cuối quý còn hụt 2000 triệu. Anh duyệt cho nhà phân phối nhận thêm hàng, hứa miệng quý sau cho trả lại, xuất hóa đơn trước để đạt chỉ tiêu.”",en:"The Quang Ngai area supervisor proposes: “We are 2000 million short at quarter end. Approve extra stock for the distributor with a verbal promise to take it back next quarter, invoice now to hit the target.”"},options:{safe:{vi:"Không duyệt đẩy hàng kèm cam kết trả lại ngoài hợp đồng; báo Giám đốc Kinh doanh Toàn quốc và tài chính, nộp dự báo thực tế và đề xuất chương trình sell-out đã phê duyệt.",en:"Reject stock loading with an off-contract return promise; inform the National Sales Director and finance, submit a realistic forecast and propose an approved sell-out program."},shortcut:{vi:"Duyệt xuất hóa đơn đẩy hàng cho đạt chỉ tiêu, quý sau xử lý hàng trả lại.",en:"Approve the invoiced stock push to hit the target and handle returns next quarter."},wait:{vi:"Không trả lời giám sát và để báo cáo quý tự phản ánh kết quả.",en:"Do not answer the supervisor and let the quarterly report speak for itself."}},questions:{vi:["Vì sao chọn SUB-DIST thay vì NEW-DIST hay DIRECT? Điều khoản hợp đồng và chính sách nào quyết định?","Trình bày cách phân bổ chỉ tiêu Quảng Ngãi và rủi ro doanh thu, tài chính khi đẩy hàng kèm cam kết trả lại."],en:["Why choose SUB-DIST over NEW-DIST or DIRECT? Which contract clause and policy decide it?","Explain the Quang Ngai target allocation and the revenue and financial risk of loading stock with a return promise."]},hints:{vi:["Đặt bản nháp cạnh chính sách kênh, đánh dấu phương án nào vi phạm hợp đồng độc quyền hoặc chính sách.","Áp dụng công thức trọng số ở SOP mục 3.2 cho đúng hai tỷ trọng của tỉnh.","Đọc lại SOP mục 4.2: doanh thu phải phản ánh giao dịch thật; cam kết ngoài hợp đồng phải được báo cáo."],en:["Place the draft next to the channel policy and flag which option breaches exclusivity or policy.","Apply the weighted formula in SOP 3.2 to the province's two shares.","Re-read SOP 4.2: revenue must reflect real transactions; side promises must be escalated."]}},learning:{summary:{vi:"Quản lý kinh doanh khu vực chịu trách nhiệm doanh số, độ phủ và lợi nhuận của một vùng: xây dựng kế hoạch, phân bổ chỉ tiêu, dẫn dắt đội giám sát và nhân viên bán hàng, phát triển và đánh giá nhà phân phối, triển khai chương trình thương mại và dự báo doanh số. Vai trò đòi hỏi tư duy chiến lược dựa trên dữ liệu, năng lực lãnh đạo đội ngũ phân tán và kỷ luật tuân thủ trong ghi nhận doanh thu và chính sách kênh.",en:"A regional sales manager owns the sales, coverage and profit of a region: building the plan, allocating targets, leading supervisors and sales reps, developing and reviewing distributors, rolling out trade programs and forecasting sales. The role needs data-driven strategic thinking, leadership of a dispersed team and discipline in revenue recognition and channel policy."},responsibilities:{vi:["Lập kế hoạch kinh doanh vùng, phân bổ chỉ tiêu theo tỉnh, kênh và ngành hàng.","Quản trị nhà phân phối: tồn kho, công nợ, độ phủ, nhân sự bán hàng và tuân thủ chính sách giá.","Huấn luyện giám sát, đi tuyến thị trường và đánh giá năng suất nhân viên bán hàng.","Triển khai chương trình thương mại, đo hiệu quả và đề xuất điều chỉnh ngân sách.","Dự báo doanh số tuần, tháng, quý và báo cáo khoảng cách so với kế hoạch."],en:["Build the regional plan and allocate targets by province, channel and category.","Manage distributors: stock, receivables, coverage, sales staff and price policy compliance.","Coach supervisors, ride routes in the market and review rep productivity.","Roll out trade programs, measure results and propose budget changes.","Forecast weekly, monthly and quarterly sales and report gaps against plan."]},competencies:[{name:{vi:"Hoạch định vùng & chỉ tiêu",en:"Territory & target planning"},desc:{vi:"Kết hợp dữ liệu lịch sử, tiềm năng và năng lực kênh để đặt chỉ tiêu thách thức nhưng khả thi.",en:"Combine history, potential and channel capacity to set stretching yet achievable targets."}},{name:{vi:"Quản trị kênh phân phối",en:"Channel management"},desc:{vi:"Thiết kế độ phủ, đánh giá nhà phân phối và xử lý xung đột kênh theo hợp đồng.",en:"Design coverage, evaluate distributors and resolve channel conflicts by contract."}},{name:{vi:"Lãnh đạo đội ngũ",en:"Team leadership"},desc:{vi:"Tuyển chọn, huấn luyện, giao mục tiêu và giữ kỷ luật cho đội bán hàng phân tán.",en:"Select, coach, set goals for and keep discipline in a dispersed sales team."}},{name:{vi:"Phân tích & dự báo",en:"Analysis & forecasting"},desc:{vi:"Đọc báo cáo sell-in, sell-out, tồn kho để dự báo sát và phát hiện rủi ro sớm.",en:"Read sell-in, sell-out and stock data to forecast accurately and spot risks early."}},{name:{vi:"Liêm chính thương mại",en:"Commercial integrity"},desc:{vi:"Không đẩy hàng ảo, không cam kết ngoài hợp đồng, báo cáo số liệu trung thực.",en:"No fake stock loading or side promises; report figures truthfully."}}],knowledge:{vi:["Mô hình phân bổ chỉ tiêu theo doanh số lịch sử, tiềm năng thị trường và năng lực độ phủ.","Chỉ số phân phối: độ phủ số, độ phủ có trọng số, số điểm bán hoạt động, số SKU mỗi điểm bán.","Quản trị nhà phân phối: tồn kho theo ngày bán (DOS), công nợ, chính sách giá, lãnh thổ độc quyền.","VAS 14 và IFRS 15 về ghi nhận doanh thu, gồm ảnh hưởng của quyền trả lại hàng.","Luật Cạnh tranh 2018 về thỏa thuận hạn chế cạnh tranh và Luật Thương mại 2005 về đại lý thương mại."],en:["Target allocation models based on sales history, market potential and coverage capacity.","Distribution metrics: numeric and weighted distribution, active outlets and SKUs per outlet.","Distributor management: days of stock (DOS), receivables, price policy and exclusive territories.","VAS 14 and IFRS 15 on revenue recognition, including the effect of return rights.","Competition Law 2018 on anti-competitive agreements and Commercial Law 2005 on commercial agency."]},tools:["Hệ thống DMS quản lý nhà phân phối","Hệ thống CRM / SFA","Bảng điều khiển BI doanh số","Bảng tính phân bổ chỉ tiêu","Ứng dụng giám sát đi tuyến"],kpis:{vi:["Tỷ lệ đạt chỉ tiêu doanh số và sản lượng theo tỉnh.","Độ phủ số và số điểm bán hoạt động hằng tháng.","Tồn kho nhà phân phối theo ngày bán trong ngưỡng chính sách.","Sai số dự báo doanh số quý."],en:["Sales and volume target achievement by province.","Numeric distribution and active outlets per month.","Distributor days of stock within the policy range.","Quarterly sales forecast error."]},day:[{time:"07:30",vi:"Họp trực tuyến đầu ngày với các giám sát, rà soát doanh số hôm qua.",en:"Morning online huddle with supervisors to review yesterday's sales."},{time:"09:00",vi:"Đi tuyến cùng nhân viên bán hàng, kiểm tra trưng bày và giá tại điểm bán.",en:"Ride a route with a rep and check displays and prices in outlets."},{time:"13:30",vi:"Làm việc với nhà phân phối về tồn kho, công nợ và kế hoạch mở điểm bán.",en:"Meet a distributor on stock, receivables and outlet expansion."},{time:"15:30",vi:"Phân tích bảng BI, điều chỉnh phân bổ chỉ tiêu và ngân sách khuyến mại.",en:"Analyze BI dashboards and adjust target and promotion allocations."},{time:"17:30",vi:"Gửi dự báo tuần và báo cáo khoảng cách kế hoạch cho giám đốc toàn quốc.",en:"Send the weekly forecast and gap report to the national director."}],mistakes:{vi:["Phân bổ chỉ tiêu chỉ theo doanh số năm trước, bỏ lỡ tỉnh có tiềm năng lớn.","Bổ nhiệm nhà phân phối mới chồng lấn lãnh thổ độc quyền, gây xung đột và tranh chấp hợp đồng.","Đẩy hàng cuối kỳ kèm cam kết trả lại, làm sai lệch doanh thu và tồn kho kênh."],en:["Allocating targets on last year's sales only and missing high-potential provinces.","Appointing a new distributor inside an exclusive territory, causing conflict and contract disputes.","Loading stock at period end with return promises, distorting revenue and channel stock."]},career:[{vi:"Giám sát bán hàng",en:"Sales supervisor"},{vi:"Quản lý bán hàng khu vực (ASM)",en:"Area Sales Manager"},{vi:"Quản lý kinh doanh vùng (RSM)",en:"Regional Sales Manager"},{vi:"Giám đốc kinh doanh toàn quốc",en:"National Sales Director"}],glossary:[{term:"Numeric distribution",vi:"Độ phủ số: tỷ lệ điểm bán có hàng trên tổng số điểm bán trong vùng.",en:"Share of outlets stocking the product among all outlets in the area."},{term:"DOS",vi:"Số ngày tồn kho: lượng tồn đủ bán bao nhiêu ngày theo tốc độ bán hiện tại.",en:"Days of stock: how many days current stock lasts at the current sales rate."},{term:"Sell-in / Sell-out",vi:"Hàng công ty bán vào nhà phân phối so với hàng nhà phân phối bán ra thị trường.",en:"Company sales into distributors versus distributor sales out to the market."},{term:"Channel stuffing",vi:"Đẩy hàng vào kênh vượt nhu cầu thực để làm đẹp doanh số kỳ báo cáo.",en:"Pushing stock into the channel beyond real demand to inflate period sales."},{term:"Sub-distributor",vi:"Nhà phân phối cấp 2 nhận hàng từ nhà phân phối chính để phủ vùng sâu, vùng xa.",en:"A second-tier distributor supplied by the main distributor to reach remote areas."}],quiz:[{q:{vi:"Chỉ tiêu vùng 20000 triệu; tỉnh X chiếm 30% doanh số năm trước và 20% tiềm năng; trọng số 60/40. Chỉ tiêu tỉnh X là bao nhiêu?",en:"Regional target 20000 million; province X has 30% of last year's sales and 20% of potential; weights 60/40. What is X's target?"},options:{vi:["6000 triệu","5200 triệu","4000 triệu","5600 triệu"],en:["6000 million","5200 million","4000 million","5600 million"]},answer:1,explain:{vi:"20000 x (0,6 x 30% + 0,4 x 20%) = 20000 x 26% = 5200 triệu.",en:"20000 x (0.6 x 30% + 0.4 x 20%) = 20000 x 26% = 5200 million."}},{q:{vi:"Số ngày tồn kho (DOS) của nhà phân phối là 45 ngày nghĩa là gì?",en:"What does a distributor DOS of 45 days mean?"},options:{vi:["Tồn kho đủ bán 45 ngày theo tốc độ bán hiện tại","Công nợ quá hạn 45 ngày","Hàng đã hết hạn sau 45 ngày","Đơn hàng giao trễ 45 ngày"],en:["Stock lasts 45 days at the current sales rate","Receivables are 45 days overdue","Goods expire after 45 days","Orders are delivered 45 days late"]},answer:0,explain:{vi:"DOS = tồn kho / bán ra bình quân ngày; DOS quá cao báo hiệu tồn ứ, nguy cơ cận date.",en:"DOS = stock / average daily sales; a high DOS signals overstock and expiry risk."}},{q:{vi:"Hợp đồng độc quyền với nhà phân phối còn hiệu lực, vùng cần tăng độ phủ. Phương án phù hợp là gì?",en:"The distributor's exclusive contract is still valid and coverage must grow. What fits?"},options:{vi:["Bổ nhiệm thêm nhà phân phối mới cùng lãnh thổ","Bán trực tiếp cho điểm lẻ bất chấp chính sách","Phát triển nhà phân phối cấp 2 dưới nhà phân phối hiện tại và đồng đầu tư đội bán hàng","Chờ hết hợp đồng mới làm gì đó"],en:["Appoint another distributor in the same territory","Sell directly to outlets against policy","Develop sub-distributors under the current distributor and co-invest in sales staff","Do nothing until the contract expires"]},answer:2,explain:{vi:"Mở rộng qua cấp 2 tôn trọng hợp đồng độc quyền và chính sách, vẫn tăng được độ phủ.",en:"Expanding through sub-distributors respects exclusivity and policy while growing coverage."}},{q:{vi:"Cấp dưới đề nghị đẩy hàng cuối quý cho nhà phân phối và hứa miệng cho trả lại. Bạn làm gì?",en:"A subordinate proposes loading stock at quarter end with a verbal return promise. What do you do?"},options:{vi:["Duyệt vì giúp đạt chỉ tiêu","Duyệt nhưng không ghi vào biên bản","Để nhà phân phối tự quyết","Từ chối, báo cấp trên và tài chính, nộp dự báo thực tế"],en:["Approve it to hit the target","Approve it without recording it","Let the distributor decide","Refuse, escalate to management and finance, submit a real forecast"]},answer:3,explain:{vi:"Cam kết trả lại ngoài hợp đồng làm sai doanh thu và che giấu rủi ro; phải từ chối và báo cáo.",en:"Off-contract return promises misstate revenue and hide risk; refuse and escalate."}}],tools_en:["Distributor management system (DMS)","CRM / SFA system","Sales BI dashboards","Sales target allocation spreadsheets","Field sales route tracking app"]}}})})(window.KKR);
